@Test
public void testIsLtrDominant() {
    // Case 1: LTR Dominant
    // Create a TextElement with English text "Hello World" which is Left-to-Right.
    // Assumes the standard TextElement constructor: 
    // TextElement(float y, float x, float width, float height, PDFont font, float fontSize, String text, float widthOfSpace)
    // We pass null for the font as it is not accessed within isLtrDominant().
    TextElement ltrElement = new TextElement(0f, 0f, 10f, 10f, null, 10f, "Hello World", 5f);
    TextChunk ltrChunk = new TextChunk(ltrElement);
    
    // Expect 1 because LTR characters > RTL characters
    org.junit.Assert.assertEquals("Should return 1 for LTR dominant text", 1, ltrChunk.isLtrDominant());

    // Case 2: RTL Dominant
    // Create a TextElement with Arabic text "\u0645\u0631\u062d\u0628\u0627" (Marhaba) which is Right-to-Left.
    TextElement rtlElement = new TextElement(0f, 0f, 10f, 10f, null, 10f, "\u0645\u0631\u062d\u0628\u0627", 5f);
    TextChunk rtlChunk = new TextChunk(rtlElement);
    
    // Expect -1 because RTL characters > LTR characters
    org.junit.Assert.assertEquals("Should return -1 for RTL dominant text", -1, rtlChunk.isLtrDominant());

    // Case 3: Neutral/Mixed
    // Create a TextElement with equal number of LTR and RTL characters.
    // "AB" (2 LTR) and "\u0627\u0628" (2 RTL)
    TextElement mixedElement = new TextElement(0f, 0f, 10f, 10f, null, 10f, "AB\u0627\u0628", 5f);
    TextChunk mixedChunk = new TextChunk(mixedElement);
    
    // Expect 0 because LTR count == RTL count
    org.junit.Assert.assertEquals("Should return 0 for equal LTR and RTL counts", 0, mixedChunk.isLtrDominant());

    // Case 4: Empty Text
    TextElement emptyElement = new TextElement(0f, 0f, 0f, 0f, null, 0f, "", 0f);
    TextChunk emptyChunk = new TextChunk(emptyElement);
    
    // Expect 0 because both counts are 0
    org.junit.Assert.assertEquals("Should return 0 for empty text", 0, emptyChunk.isLtrDominant());
}
